  if(req.method==='GET'&&url.pathname==='/bataar/privacy'){res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'"});return res.end(await (await import('node:fs/promises')).readFile(new URL('./bataar-privacy.html',import.meta.url),'utf8'));}
